  this.TW = this.R.W("Rebalancing", "Rebalansowanie", "\u0420\u0435\u0431\u0430\u043b\u0430\u043d\u0441\u0438\u0440\u043e\u0432\u043a\u0430", "\u0420\u0435\u0431\u0430\u043b\u0430\u043d\u0441\u0443\u0432\u0430\u043d\u043d\u044f");
  this.U3 = this.R.W("From year", "Od roku", "\u0421 \u0433\u043e\u0434\u0430", "\u0417 \u0440\u043e\u043a\u0443");
  this.TH = this.R.W("At the start", "Na start", "\u041d\u0430 \u0441\u0442\u0430\u0440\u0442\u0435", "\u041d\u0430 \u0441\u0442\u0430\u0440\u0442\u0456");
