  this.Tt = this.R.W("Account", "Rachunek", "\u0421\u0447\u0451\u0442", "\u0420\u0430\u0445\u0443\u043d\u043e\u043a");
  this.U0 = this.R.W("Check the plan", "Sprawd\u017a plan", "\u041f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c \u043f\u043b\u0430\u043d", "\u041f\u0435\u0440\u0435\u0432\u0456\u0440\u0438\u0442\u0438 \u043f\u043b\u0430\u043d");
  this.U4 = this.R.W("the shares add up to 100%", "udzia\u0142y sumuj\u0105 si\u0119 do 100%", "\u0434\u043e\u043b\u0438 \u0432 \u0441\u0443\u043c\u043c\u0435 \u0434\u0430\u044e\u0442 100%", "\u0447\u0430\u0441\u0442\u043a\u0438 \u0432 \u0441\u0443\u043c\u0456 \u0434\u0430\u044e\u0442\u044c 100%");
  this.TP = this.R.W("choose at least one asset", "wybierz co najmniej jedno aktywo", "\u0432\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u0445\u043e\u0442\u044f \u0431\u044b \u043e\u0434\u0438\u043d \u0430\u043a\u0442\u0438\u0432", "\u043e\u0431\u0435\u0440\u0456\u0442\u044c \u0445\u043e\u0447\u0430 \u0431 \u043e\u0434\u0438\u043d \u0430\u043a\u0442\u0438\u0432");
  this.TB = this.R.W("Change the plan", "Zmie\u0144 plan", "\u0418\u0437\u043c\u0435\u043d\u0438\u0442\u044c \u043f\u043b\u0430\u043d", "\u0417\u043c\u0456\u043d\u0438\u0442\u0438 \u043f\u043b\u0430\u043d");
  this.Tx = this.R.W("Start over", "Od nowa", "\u0417\u0430\u043d\u043e\u0432\u043e", "\u0421\u043f\u043e\u0447\u0430\u0442\u043a\u0443");
  this.TY = this.R.W("What the plan did", "Co zrobi\u0142 plan", "\u0427\u0442\u043e \u0441\u0434\u0435\u043b\u0430\u043b \u043f\u043b\u0430\u043d", "\u0429\u043e \u0437\u0440\u043e\u0431\u0438\u0432 \u043f\u043b\u0430\u043d");
  this.TV = this.R.W("Put in", "Wp\u0142acono", "\u0412\u043b\u043e\u0436\u0435\u043d\u043e", "\u0412\u043a\u043b\u0430\u0434\u0435\u043d\u043e");
  this.Ib = this.R.W("Value at the end", "Warto\u015b\u0107 na ko\u0144cu", "\u0421\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u044c \u0432 \u043a\u043e\u043d\u0446\u0435", "\u0412\u0430\u0440\u0442\u0456\u0441\u0442\u044c \u043d\u0430\u043f\u0440\u0438\u043a\u0456\u043d\u0446\u0456");
  this.I6 = this.R.W("After the tax if sold", "Po podatku przy sprzeda\u017cy", "\u041f\u043e\u0441\u043b\u0435 \u043d\u0430\u043b\u043e\u0433\u0430 \u043f\u0440\u0438 \u043f\u0440\u043e\u0434\u0430\u0436\u0435", "\u041f\u0456\u0441\u043b\u044f \u043f\u043e\u0434\u0430\u0442\u043a\u0443 \u043f\u0440\u0438 \u043f\u0440\u043e\u0434\u0430\u0436\u0443");
  this.DK = this.R.W("Growth a year (of the plan)", "Wzrost rocznie (planu)", "\u0420\u043e\u0441\u0442 \u0432 \u0433\u043e\u0434 (\u043f\u043b\u0430\u043d\u0430)", "\u0417\u0440\u043e\u0441\u0442\u0430\u043d\u043d\u044f \u043d\u0430 \u0440\u0456\u043a (\u043f\u043b\u0430\u043d\u0443)");
  this.Ia = this.R.W("Growth a year (of your money)", "Wzrost rocznie (twoich pieni\u0119dzy)", "\u0420\u043e\u0441\u0442 \u0432 \u0433\u043e\u0434 (\u0432\u0430\u0448\u0438\u0445 \u0434\u0435\u043d\u0435\u0433)", "\u0417\u0440\u043e\u0441\u0442\u0430\u043d\u043d\u044f \u043d\u0430 \u0440\u0456\u043a (\u0432\u0430\u0448\u0438\u0445 \u0433\u0440\u043e\u0448\u0435\u0439)");
  this.U8 = this.R.W("Worst year", "Najgorszy rok", "\u0425\u0443\u0434\u0448\u0438\u0439 \u0433\u043e\u0434", "\u041d\u0430\u0439\u0433\u0456\u0440\u0448\u0438\u0439 \u0440\u0456\u043a");
  this.I9 = this.R.W("Deepest fall", "Najg\u0142\u0119bszy spadek", "\u0413\u043b\u0443\u0431\u043e\u0447\u0430\u0439\u0448\u0435\u0435 \u043f\u0430\u0434\u0435\u043d\u0438\u0435", "\u041d\u0430\u0439\u0433\u043b\u0438\u0431\u0448\u0435 \u043f\u0430\u0434\u0456\u043d\u043d\u044f");
  this.Tz = this.R.W("Back to the top after", "Powr\u00f3t do szczytu po", "\u0412\u043e\u0437\u0432\u0440\u0430\u0442 \u043a \u0432\u0435\u0440\u0448\u0438\u043d\u0435 \u0447\u0435\u0440\u0435\u0437", "\u041f\u043e\u0432\u0435\u0440\u043d\u0435\u043d\u043d\u044f \u0434\u043e \u0432\u0435\u0440\u0448\u0438\u043d\u0438 \u0447\u0435\u0440\u0435\u0437");
